// Aplana el array de efectos en una lista de envios.
//
// No hace falta un Switch por tipo: el nucleo ya ha resuelto A QUIEN va
// cada efecto (destinatarios, desde escalado del YAML) y CON QUE TEXTO
// (compuesto desde avisos del YAML). n8n solo manda texto a destino.
// Si enrutaramos aqui tambien, tendriamos dos criterios que acabarian
// desincronizados.
//
// El ORDEN del array importa y se conserva: al reagendar sale primero
// la anulacion y luego el aviso de la cita nueva. Al reves, recepcion
// lee "mete esta" y despues "lo anterior no vale", y mete la que no era.

const salida = [];
const respuesta = $input.first().json;
const efectos = respuesta.efectos ?? [];

for (const efecto of efectos) {
  const destinatarios = efecto.destinatarios ?? [];

  // avisar_a_recepcion_de_anulacion trae el texto util en
  // mensajeParaRecepcion de la respuesta, no en el propio efecto.
  const texto = efecto.texto ?? respuesta.mensajeParaRecepcion ?? null;

  // Los efectos que no van a una persona (registrar_baja y demas)
  // no tienen destinatarios: se ignoran aqui a proposito.
  if (!texto || destinatarios.length === 0) continue;

  for (const destinatario of destinatarios) {
    if (destinatario.canal !== 'whatsapp') continue;

    salida.push({
      json: {
        tipo: efecto.tipo,
        destino: destinatario.destino,
        paraQuien: destinatario.nombre,
        texto
      }
    });
  }
}

return salida;

// Meta manda muchos webhooks que NO son mensajes: acuses de entrega,
// lecturas y cambios de estado. Sin filtrar, el nucleo recibiria basura
// y devolveria 400. Devolver cero items para el workflow por si solo.
//
// PENDIENTE: los audios se descartan aqui en silencio. En estetica la
// gente manda notas de voz a diario, y hoy el paciente no recibe nada
// y cree que ha llegado.

const salida = [];

for (const item of $input.all()) {
  const cuerpo = item.json.body ?? item.json;

  for (const entrada of cuerpo.entry ?? []) {
    for (const cambio of entrada.changes ?? []) {
      const valor = cambio.value ?? {};
      const contactos = valor.contacts ?? [];

      for (const mensaje of valor.messages ?? []) {
        if (mensaje.type !== 'text') continue;

        const contacto = contactos.find((c) => c.wa_id === mensaje.from);
        const nombrePerfil = (contacto?.profile?.name ?? '').trim();

        salida.push({
          json: {
            idMensaje: mensaje.id,
            telefono: '+' + mensaje.from,
            nombre: (nombrePerfil || 'Paciente').slice(0, 100),
            texto: (mensaje.text?.body ?? '').slice(0, 4000),
            phoneNumberId: valor.metadata?.phone_number_id ?? null
          }
        });
      }
    }
  }
}

return salida;
